import collections

def group_by_dept(rows):
    grouped = collections.defaultdict(int)
    for row in rows:
        dept = row['dept']
        sales = row['sales']
        grouped[dept] += sales
    return grouped

def main():
    rows = [
        {'dept': 'A', 'sales': 120},
        {'dept': 'B', 'sales': 80},
        {'dept': 'A', 'sales': 95},
        {'dept': 'C', 'sales': 40},
        {'dept': 'B', 'sales': 70}
    ]
    result = group_by_dept(rows)
    print(result)

if __name__ == '__main__':
    main()

